/* The agenda is a once-a-day push. 07:30 is primary; 11:30 and 15:30 exist
   only because the host may be asleep at 07:30. A successful push already
   recorded for today means this slot must stay quiet - late is acceptable,
   duplicate is not. agenda_runs is written only after a confirmed delivery, so
   "has a row for today" equals "something actually reached the user". */
const H = { 'X-N8N-API-KEY': $env.N8N_API_KEY };
const api = (path, qs) => this.helpers.httpRequest({ method: 'GET', url: 'http://localhost:5678/api/v1' + path, headers: H, qs });
const today = new Date(Date.now() + 8 * 3600000).toISOString().slice(0, 10);
let rows = [];
try {
  const tables = (await api('/data-tables', { limit: 100 })).data || [];
  const id = (tables.find((t) => t.name === 'agenda_runs') || {}).id;
  if (id) rows = (await api('/data-tables/' + id + '/rows', { limit: 250 })).data || [];
} catch (e) {
  rows = []; /* table missing or API hiccup: a late push beats a silent day */
}
const sentToday = rows.some((r) => String(r.agenda_date || '') === today && Number(r.sent || 0) === 1);
if (sentToday) return [];
return $input.all();

/* Auth gate - only meaningful for the manual webhook input
   (schedule-triggered items carry no headers). */
const input = $input.first().json;
if (input.headers) {
  const provided = String(input.headers.authorization || '').replace(/^Bearer\s+/i, '');
  if (!provided || provided !== $env.CHAT_API_KEY) {
    return [{ json: { __error: true, status: 401, body: { error: { message: 'Invalid API key. Provide it via the Authorization: Bearer header.', type: 'authentication_error', code: 'invalid_api_key' } } } }];
  }
}
return [{ json: { ok: true } }];

/* Build today's agenda from todos, delegated todos and reminders.
   Read-only: nothing is mutated here. The only decision is whether the
   current set differs from the last SUCCESSFUL push (agenda_runs), so an
   unchanged day stays silent. Timezone: Asia/Shanghai (UTC+8). */
const H = { 'X-N8N-API-KEY': $env.N8N_API_KEY };
const api = (path, qs) => this.helpers.httpRequest({ method: 'GET', url: 'http://localhost:5678/api/v1' + path, headers: H, qs });
const tables = (await api('/data-tables', { limit: 100 })).data || [];
const idOf = (name) => (tables.find((t) => t.name === name) || {}).id;
const load = async (name, qs) => {
  const id = idOf(name);
  if (!id) return [];
  return (await api('/data-tables/' + id + '/rows', qs)).data || [];
};

if (!idOf('todos') || !idOf('reminders')) {
  throw new Error('todos/reminders data table missing - run n8n/scripts/deploy.mjs first');
}

const [todos, reminders, people, runs] = await Promise.all([
  load('todos', { limit: 250 }),
  load('reminders', { limit: 250 }),
  load('people', { limit: 200 }),
  load('agenda_runs', { limit: 250 }),
]);

const SHIFT = 8 * 3600000;
const today = new Date(Date.now() + SHIFT).toISOString().slice(0, 10);
const endOfToday = Date.parse(today + 'T23:59:59.999Z') - SHIFT;
const localDay = (iso) => {
  const t = Date.parse(iso || '');
  return Number.isFinite(t) ? new Date(t + SHIFT).toISOString().slice(0, 10) : '';
};
const localTime = (iso) => {
  const t = Date.parse(iso || '');
  return Number.isFinite(t) ? new Date(t + SHIFT).toISOString().slice(11, 16) : '';
};
const daysLate = (due) => {
  const t = Date.parse(due || '');
  return Number.isFinite(t) ? Math.max(1, Math.round((Date.parse(today) - t) / 86400000)) : 0;
};
const nameOf = (ref) => {
  if (!ref) return '';
  const p = people.find((x) => x.name === ref);
  return p ? (p.display_name || p.name) : ref;
};

const open = todos.filter((t) => t.status === 'open');
const mine = open.filter((t) => !(t.owner_ref || '') && t.due_date && t.due_date <= today);
const waiting = open.filter((t) => (t.owner_ref || '') && !(t.ack_at || '') && (!t.due_date || t.due_date <= today));
const dueReminders = reminders.filter((r) => r.status === 'pending' && localDay(r.due_at) && localDay(r.due_at) <= today && Date.parse(r.due_at) <= endOfToday);

const items = [];
for (const t of mine) {
  items.push({ key: 'todo:' + t.id, kind: 'todo', id: t.id, text: String(t.text || '').slice(0, 120), bucket: t.due_date < today ? 'overdue' : 'today', due: t.due_date, days: t.due_date < today ? daysLate(t.due_date) : 0, owner: '', at: '' });
}
for (const t of waiting) {
  const late = t.due_date && t.due_date < today;
  items.push({ key: 'wait:' + t.id, kind: 'delegated', id: t.id, text: String(t.text || '').slice(0, 120), bucket: late ? 'overdue' : (t.due_date === today ? 'today' : 'waiting'), due: t.due_date || '', days: late ? daysLate(t.due_date) : 0, owner: nameOf(t.owner_ref), at: '' });
}
for (const r of dueReminders) {
  const day = localDay(r.due_at);
  items.push({ key: 'rem:' + r.id, kind: 'reminder', id: r.id, text: String(r.text || '').slice(0, 120), bucket: day < today ? 'overdue' : 'today', due: day, days: day < today ? daysLate(day) : 0, owner: nameOf(r.owner_ref), at: localTime(r.due_at) });
}

/* One stable line per item; sorting keeps the hash independent of API order. */
const fingerprint = require('crypto').createHash('sha256')
  .update(JSON.stringify(items.map((i) => [i.key, i.text, i.bucket, i.due, i.at, i.owner]).sort()))
  .digest('hex');

const overdue = items.filter((i) => i.bucket === 'overdue').sort((a, b) => b.days - a.days);
const dueToday = items.filter((i) => i.bucket === 'today').sort((a, b) => String(a.at || '99').localeCompare(String(b.at || '99')));
const waitingItems = items.filter((i) => i.bucket === 'waiting');

const line = (i) => {
  if (i.kind === 'reminder') {
    const stamp = i.bucket === 'overdue' ? i.due : i.at;
    return '- ' + (stamp ? stamp + ' ' : '') + i.text + (i.bucket === 'overdue' ? ' (逾期 ' + i.days + ' 天)' : '');
  }
  const who = i.kind === 'delegated' && i.owner ? ' - 等 ' + i.owner : '';
  if (i.bucket === 'overdue') return '- #' + i.id + ' ' + i.text + ' (逾期 ' + i.days + ' 天)' + who;
  return '- #' + i.id + ' ' + i.text + who;
};
const section = (title, rows) => rows.length
  ? String.fromCharCode(10) + title + ' (' + rows.length + ')' + String.fromCharCode(10) + rows.slice(0, 10).map(line).join(String.fromCharCode(10)) + (rows.length > 10 ? String.fromCharCode(10) + '... 还有 ' + (rows.length - 10) + ' 项' : '') + String.fromCharCode(10)
  : '';

const message = String(
  '今日议程 · ' + today + String.fromCharCode(10) +
  section('逾期', overdue) +
  section('今天到期', dueToday) +
  section('等待他人', waitingItems) +
  String.fromCharCode(10) + '共 ' + items.length + ' 项 · 内容无变化时不会重复推送'
).slice(0, 3500);

/* Rows API caps limit at 250 and rejects raw sortBy values, so sort here. */
const last = runs.slice().sort((a, b) => String(b.createdAt || '').localeCompare(String(a.createdAt || '')))[0] || {};
const lastFingerprint = String(last.fingerprint || '');
const should_send = items.length > 0 && fingerprint !== lastFingerprint;

return [{ json: {
  ok: true,
  should_send,
  fingerprint,
  item_count: items.length,
  counts: { overdue: overdue.length, today: dueToday.length, waiting: waitingItems.length },
  agenda_date: today,
  kind: '今日议程',
  message: should_send ? message : '',
  preview: message.slice(0, 300),
  last_fingerprint: lastFingerprint,
} }];

/* Report the failure without pretending the digest was sent: no row is
   written, so the next slot (or tomorrow) retries. */
const a = $('Load & Build').first().json;
const d = $input.first().json || {};
return [{ json: { ok: false, sent: false, reason: String(d.reason || 'delivery_failed'), agenda_date: a.agenda_date, item_count: a.item_count, counts: a.counts, fingerprint: a.fingerprint } }];

/* Persist only what was actually pushed. A failed delivery leaves no row,
   so the next run still compares against the last SUCCESSFUL digest. */
const a = $('Load & Build').first().json;
return [{ json: { agenda_date: a.agenda_date, fingerprint: a.fingerprint, item_count: a.item_count, sent: 1, preview: a.preview } }];
